var assert = require('assert');
var bytes = require('..');

describe('proof', function () {
  it('fails on the patched build', function () {
    // The original regex /^.../ ensures that + and - signs are only matched at the start
    // The patched regex /.../ allows + and - signs anywhere, breaking parsing
    assert.strictEqual(bytes.parse('+1kb'), 1024);
    assert.strictEqual(bytes.parse('-1kb'), -1024);
    assert.strictEqual(bytes.parse('1+kb'), null); // Should be invalid, but patched version matches
    assert.strictEqual(bytes.parse('1-kb'), null); // Should be invalid, but patched version matches
  });
});

