var assert = require('assert');
var bytes = require('..');

describe('proof', function () {
  it('fails on the patched build', function () {
    // Original behavior: decimalPlaces should default to 2 if not provided
    // Patched behavior: always uses 2, ignoring options.decimalPlaces
    assert.strictEqual(bytes(1234.5678, { decimalPlaces: 3 }), '1.235KB');
    assert.strictEqual(bytes(1234.5678, { decimalPlaces: 0 }), '1KB');
    assert.strictEqual(bytes(1234.5678, { decimalPlaces: 5 }), '1.23457KB');
    // The patched version ignores decimalPlaces and always uses 2
    assert.strictEqual(bytes(1234.5678, { decimalPlaces: 0 }), '1.23KB'); // This should be '1KB'
  });
});

