var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('fails on the patched build', function () {
    // The original code converts 1 year to milliseconds (365.25 * 24 * 60 * 60 * 1000)
    // The patched code incorrectly divides by the year constant, yielding a very small number
    const original = ms('1y');
    const patched = ms('1y');
    assert.notEqual(patched, original, 'Parsing "1y" should not return the same result as the original');
    assert.strictEqual(patched, 1 / (365.25 * 24 * 60 * 60 * 1000), 'Parsing "1y" should return 1 divided by the number of milliseconds in a year');
  });
});
